import pandas as pd

class Solution:
    def find_valid_triplets(self, school_a: pd.DataFrame, school_b: pd.DataFrame,
                            school_c: pd.DataFrame) -> pd.DataFrame:
        res = []
        for _, a in school_a.iterrows():
            for _, b in school_b.iterrows():
                for _, c in school_c.iterrows():
                    names = {a.student_name, b.student_name, c.student_name}
                    ids = {a.student_id, b.student_id, c.student_id}
                    if len(names) == 3 and len(ids) == 3:
                        res.append([a.student_name, b.student_name, c.student_name])
        return pd.DataFrame(res, columns=['member_A', 'member_B', 'member_C'])

