struct Student { int id; string name; };

class Solution {
public:
    vector<array<string, 3>> findValidTriplets(vector<Student>& a,
                                               vector<Student>& b,
                                               vector<Student>& c) {
        vector<array<string, 3>> res;
        for (auto& x : a)
            for (auto& y : b)
                for (auto& z : c)
                    if (x.name != y.name && x.name != z.name && y.name != z.name &&
                        x.id != y.id && x.id != z.id && y.id != z.id)
                        res.push_back({x.name, y.name, z.name});
        return res;
    }
};

