class Solution {
    static class Student { int id; String name;
        Student(int id, String name) { this.id = id; this.name = name; } }

    public List<String[]> findValidTriplets(List<Student> a, List<Student> b, List<Student> c) {
        List<String[]> res = new ArrayList<>();
        for (Student x : a)
            for (Student y : b)
                for (Student z : c)
                    if (!x.name.equals(y.name) && !x.name.equals(z.name) && !y.name.equals(z.name)
                            && x.id != y.id && x.id != z.id && y.id != z.id)
                        res.add(new String[]{x.name, y.name, z.name});
        return res;
    }
}

